def func_order_series_convert_code(code):
    func_list = ['order', 'order_target', 'order_value', 'order_target_value']
    def convert_code(code):
        pattern = '\\b%s\\((.*)\\)' % func
        def replace_args(match):
            input_string = remove_space_in_function_call(match.group(1))
            args = input_string.split(',')
            if len(args) != 5:
                user_log.info('转换失败！%s函数转换成PTrade接口时必须入参5个参数，order(security, amount, style=None, side="long", pindex=0)' % func)
                return match.group(0)
            else:
                new_args = [args[0].strip(), args[1].strip()]
                price_type_info = args[2]
                limit_price_keywords_1 = ['LimitOrderStyle']
                limit_price_keywords_2 = ['None']
                if any((keyword in price_type_info for keyword in limit_price_keywords_1)):
                    original = 'style=LimitOrderStyle(p)'
                    result = re.sub('style=LimitOrderStyle\\((.*?)\\)', 'limit_price=\\1', original)
                elif any((keyword in price_type_info for keyword in limit_price_keywords_2)):
                    result = 'limit_price=None'
                else:
                    user_log.info('转换失败！%s函数转换成PTrade接口时,style不能选市价类型MarketOrderStyle，PTrade中该函数仅支持限价委托。交易场景的市价委托可以使用PTrade的order接口order_market函数' % func)
                    return match.group(0)
                new_args.append(result)
                user_log.info('转换成功！%s函数转换后函数名不变，入参有变化' % func)
                return '%s(' % func + ','.join(new_args) + ')'
        new_code = re.sub(pattern, replace_args, code)
        return new_code
    for func in func_list:
        code = convert_code(code)
    else:
        return code
